import sys
import math

MODULUS = 998244353
ROOT = 3

def mod_pow(base, exp):
    result = 1
    base %= MODULUS
    while exp > 0:
        if exp & 1:
            result = (result * base) % MODULUS
        base = (base * base) % MODULUS
        exp >>= 1
    return result

def bit_reversal(array, size):
    j = 0
    for i in range(1, size):
        bit = size >> 1
        while j >= bit:
            j -= bit
            bit >>= 1
        j += bit
        if i < j:
            array[i], array[j] = array[j], array[i]

def perform_fft(array, size, direction):
    bit_reversal(array, size)
    length = 2
    while length <= size:
        wlen = mod_pow(ROOT, (MODULUS - 1) // length)
        if direction == -1:
            wlen = mod_pow(wlen, MODULUS - 2)
        for start in range(0, size, length):
            w = 1
            for k in range(start, start + length // 2):
                u = array[k]
                v = array[k + length // 2] * w % MODULUS
                array[k] = (u + v) % MODULUS
                array[k + length // 2] = (u - v + MODULUS) % MODULUS
                w = w * wlen % MODULUS
        length <<= 1
    if direction == -1:
        inv_size = mod_pow(size, MODULUS - 2)
        for i in range(size):
            array[i] = array[i] * inv_size % MODULUS

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])
    halfN = n // 2
    len_power = 1
    while len_power < (9 * halfN + 1):
        len_power <<= 1
    array = [0] * len_power
    for i in range(m):
        x = int(input_data[2 + i])
        array[x] = 1
    perform_fft(array, len_power, 1)
    for i in range(len_power):
        if array[i] != 0:
            array[i] = mod_pow(array[i], halfN) % MODULUS
    perform_fft(array, len_power, -1)
    total_sum = 0
    for i in range(len_power):
        total_sum = (total_sum + array[i] * array[i]) % MODULUS
    print(total_sum)

if __name__ == "__main__":
    main()

